out, bad = [], []
for i, (inv, sid, text, quote, topic) in enumerate(C, 1):
    s = src[sid]
    if not quote_in_source(quote, s["text"]):
        bad.append((i, sid, quote[:80]))
    out.append({"id": f"c-{i:04d}", "inv": inv, "text": text, "quote": quote, "sourceId": sid,
                "sourceUrl": s["url"], "topic": topic, "extractedBy": "llm"})
print("claims", len(out), "bad", len(bad))
for b in bad: print(b)
from collections import Counter
print(Counter(c["inv"] for c in out))
if not bad:
    json.dump(out, open(f"{ROOT}/data/legacy_seed/claims.json", "w"), indent=1, ensure_ascii=False)
